const msg = $input.first().json;
let text = "";
let telegramId = "test_user";
let firstName = "Usuario";
let lastName = "";
let chatId = "test_chat";

const message = msg.message || msg.edited_message;
if (message) {
  text = message.text || '';
  telegramId = String(message.from.id);
  firstName = message.from.first_name || '';
  lastName = message.from.last_name || '';
  chatId = String(message.chat.id);
} else if (msg.chatInput) {
  text = msg.chatInput;
  telegramId = msg.sessionId || "chat_test";
  chatId = msg.sessionId || "chat_test";
} else if (msg.text) {
  text = msg.text;
}

return [{ json: { telegramId, chatId, firstName, lastName, text: text.trim(), timestamp: new Date().toISOString() } }];

const msg = $input.first().json;
const text = (msg.text || "").trim();
const textLower = text.toLowerCase();

// 1. Guardrail (Filtro de palabras inapropiadas)
const badWords = ["mierda", "puto", "puta", "pendejo", "pendeja", "maricon", "marica", "gonorrea", "malparido", "hp", "pirobo"];
let violatesGuardrail = false;
for (const word of badWords) {
  if (textLower.includes(word)) {
    violatesGuardrail = true;
    break;
  }
}

let tipo = 'menu';
let extraidoID = null;

if (violatesGuardrail) {
  tipo = 'guardrail';
} else if (textLower.startsWith('/tarifa') || textLower.includes('tarifa') || textLower.includes('precio') || textLower.includes('costo') || textLower.includes('vale')) {
  tipo = 'tarifa';
} else if (textLower.startsWith('/salir') || textLower.includes('salir') || textLower.includes('adios')) {
  tipo = 'salir';
} else if (textLower.startsWith('/miscursos') || textLower.startsWith('/estado') || textLower.includes('estado academico') || textLower.includes('estado académico') || textLower.includes('mis cursos')) {
  tipo = 'estado_academico';
  const match = text.match(/\d+/);
  if (match) {
    extraidoID = match[0];
  }
} else if (textLower.startsWith('/preguntas') || textLower.includes('preguntas generales') || textLower.includes('pregunta')) {
  tipo = 'preguntas_generales';
} else if (/^\d+$/.test(text)) {
  // El usuario escribió SOLO su número de ID -> lo tratamos como solicitud de estado académico
  tipo = 'estado_academico';
  extraidoID = text;
} else {
  if (text.length > 12) {
    tipo = 'preguntas_generales';
  } else {
    tipo = 'menu';
  }
}

return [{
  json: {
    ...msg,
    tipo,
    violatesGuardrail,
    extraidoID,
    preguntaOriginal: text
  }
}];

