// Este nodo recupera la respuesta generada por cualquiera de los caminos que se haya ejecutado
let respuesta = "Lo siento, ocurrió un error al procesar tu solicitud.";

const nodosRespuesta = [
  'Respuesta Guardrail',
  'Respuesta Tarifa',
  'Respuesta Salir',
  'Respuesta Menú',
  'Solicitar ID',
  'Formatear Respuesta Estado',
  'Formatear Respuesta RAG'
];

for (const nombreNodo of nodosRespuesta) {
  try {
    const datosNodo = $(nombreNodo).item;
    if (datosNodo && datosNodo.json && datosNodo.json.respuesta) {
      respuesta = datosNodo.json.respuesta;
      break; // Detiene la búsqueda cuando encuentra el nodo que sí se ejecutó
    }
  } catch (error) {
    // Ignora los errores de los nodos que no se ejecutaron en esta sesión
  }
}

// Retorna la respuesta en la propiedad 'output' que requiere el nodo de chat
return [{ json: { output: respuesta } }];
